window.ORB_DATA={"id": "dia-de-muertos", "title": {"en": "Día de Muertos — A Place for Those We Remember", "es": "Día de Muertos — Un lugar para quienes recordamos"}, "revision": "2026-09-10.3", "languages": ["en", "es"], "voices": {"en": {"id": "af_heart", "name": "Kokoro Heart"}, "es": {"id": "ef_dora", "name": "Kokoro Dora"}}, "sources": {"unesco": {"title": "UNESCO · Indigenous festivity dedicated to the dead", "url": "https://ich.unesco.org/en/lists?RL=00054"}, "inpi": {"title": "INPI · Los elementos de una ofrenda", "url": "https://www.gob.mx/inpi/articulos/conoces-el-significado-de-los-elementos-de-una-ofrenda-de-dia-de-muertos?idiom=es"}, "history": {"title": "INAH · El origen del Día de Muertos", "url": "https://www.inah.gob.mx/especiales-inah/articulos/el-origen-del-dia-de-muertos"}, "regions": {"title": "INAH · Día de Muertos: tradiciones regionales y videos", "url": "https://inah.gob.mx/images/interactivos/20251031_Dia_De_Muertos/"}, "xantolo": {"title": "UNESCO México · Xantolo en la Huasteca Potosina", "url": "https://www.unesco.org/es/articles/xantolo-la-fiesta-teenek-que-arropa-los-antepasados-y-quienes-vienen-de-paso"}, "huehues": {"title": "UNESCO México · Huehues y la fiesta huasteca", "url": "https://www.unesco.org/es/articles/huehues-una-identidad-de-la-fiesta-los-muertos-de-la-cultura-huasteca"}, "smithsonian": {"title": "Smithsonian · An Altar for the Dead", "url": "https://www.si.edu/collections/snapshot/altar-dead"}, "change": {"title": "Smithsonian Folklife · Altered Altars", "url": "https://folklife.si.edu/magazine/altered-altars-changing-traditions-dia-de-los-muertos"}, "chicano": {"title": "Smithsonian American Art Museum · Traditions and Change", "url": "https://americanart.si.edu/blog/dia-de-los-muertos-united-states"}, "cisneros": {"title": "Smithsonian · Exploring Día de los Muertos with Sandra Cisneros", "url": "https://americanhistory.si.edu/explore/stories/exploring-dia-de-los-muertos-sandra-cisneros"}, "facts": {"title": "Smithsonian · Five Facts About Día de los Muertos", "url": "https://www.si.edu/stories/5-facts-about-dia-de-los-muertos-day-dead"}, "agua": {"title": "CONAGUA · El agua es vida… hasta para los muertos", "url": "https://www.gob.mx/conagua/articulos/el-agua-es-vida-hasta-para-los-muertos"}, "cdmx": {"title": "Ciudad de México · Ofrendas de Día de Muertos", "url": "https://mexicocity.cdmx.gob.mx/day-of-the-dead-ofrendas/"}, "parade": {"title": "Secretaría de Cultura CDMX · Gran Desfile 2024", "url": "https://www.youtube.com/watch?v=qSjmox36y3w"}, "publicaltar": {"title": "Naciones Unidas en México · Ofrendas por la vida y la paz", "url": "https://mexico.un.org/es/282611-d%C3%ADa-de-muertos-onu-se-suma-tradici%C3%B3n-popular-mexicana-con-ofrendas-por-la-vida-y-la-paz"}, "art": {"title": "Secretaría de Cultura · Muerte y fiesta: gráfica mexicana", "url": "https://www.gob.mx/cultura/prensa/el-arte-del-munal-viaja-a-chicago-con-muerte-y-fiesta?idiom=es-MX"}, "calendar": {"title": "INAH · Día de Muertos, un sincretismo religioso", "url": "https://www.inah.gob.mx/foto-del-dia/dia-de-muertos-un-sincretismo-religioso"}, "pomuch": {"title": "INAH · Janal pixan y la limpieza de huesos", "url": "https://inah.gob.mx/foto-del-dia/janal-pixan-y-la-limpieza-de-huesos"}, "anthology": {"title": "INPI · El Día de Muertos entre los pueblos indígenas de México", "url": "https://dili.inpi.gob.mx/wp-content/uploads/2024/09/antologia-dia-de-muertos-pueblos-indigenas-de-mexico-inpi.pdf"}, "unam": {"title": "UNAM · Megaofrenda 2025: migraciones y memoria", "url": "https://www.gaceta.unam.mx/ceremonia-de-premiacion-concursos-megaofrenda-2025/"}, "once": {"title": "Canal Once · Celebración de Día de Muertos", "url": "https://www.youtube.com/watch?v=lM-tUspn3aw"}}, "nodes": [{"id": "welcome", "parent": null, "photo": "90433159", "sources": ["unesco", "smithsonian", "once"], "title": {"en": "A place for those we remember", "es": "Un lugar para quienes recordamos"}, "body": {"en": "A parade catches the eye: color, motion, faces transformed by paint. Stay a little longer and a different question appears. For whom are the flowers being arranged? A photograph and a favorite dish can turn that question toward one particular life. This ORB begins with the spectacle and follows the work, relationships, and histories behind it.\n\nDía de Muertos brings together many practices of honoring the dead in Mexico and in communities beyond its borders. Their meanings and calendars differ. In traditions documented by UNESCO, deceased loved ones are welcomed during a temporary return. Here that is presented as a cultural and spiritual belief, with respect for people who understand remembrance differently.\n\nExplore six doorways, look closely at real photographs, and hear the readings in English or Spanish. Every branch returns to the same question: how do people make room for those they remember?", "es": "Un desfile atrae la mirada: color, movimiento, rostros transformados por el maquillaje. Si te quedas un momento más, aparece otra pregunta. ¿Para quién se acomodan las flores? Una fotografía y un platillo favorito pueden llevar esa pregunta hacia una vida en particular. Este ORB comienza con la fiesta y sigue el trabajo, las relaciones y las historias que la hacen posible.\n\nEl Día de Muertos reúne muchas maneras de honrar a los difuntos en México y en comunidades fuera del país. Sus significados y calendarios varían. En las tradiciones documentadas por la UNESCO, se recibe a los seres queridos durante su regreso temporal. Aquí se presenta como una creencia cultural y espiritual, respetando también otras formas de entender el recuerdo.\n\nExplora seis puertas, observa fotografías reales y escucha las lecturas en inglés o español. Cada recorrido vuelve a la misma pregunta: ¿cómo creamos un lugar para quienes recordamos?"}, "kind": "root", "anchor": "in-view", "children": ["memory", "offering", "hands", "places", "histories", "future"], "group": "welcome", "level": 0, "moves": {"up": null, "down": "memory", "left": null, "right": null, "forward": null, "backward": null}, "thread": {"en": "No authored temporal connection at this point.", "es": "No hay una conexión temporal escrita para este punto."}}, {"id": "memory", "parent": "welcome", "photo": "29397392", "sources": ["smithsonian", "cisneros"], "title": {"en": "The photograph: a particular life", "es": "La fotografía: una vida en particular"}, "body": {"en": "A portrait gives an ofrenda an address. The person remembered has a face, a name, and a history that cannot be explained by a list of holiday symbols. A favorite food or familiar possession may carry a story that only relatives or friends can tell. A visitor can notice the care without pretending to know that story.\n\nThis is a useful way into the celebration: begin with the particular. Ask who is being remembered, who arranged the offering, and what they chose to include. Then widen the view to family, community, and history. A museum altar may honor a public figure; a household offering may gather several generations. Their purposes overlap, but their settings and relationships matter.", "es": "Un retrato le da un destinatario a la ofrenda. La persona recordada tiene un rostro, un nombre y una historia que no cabe en una lista de símbolos de la festividad. Un alimento favorito o un objeto conocido puede guardar una historia que solo sus familiares o amistades saben contar. Quien visita puede reconocer ese cuidado sin fingir que conoce la historia.\n\nEsta es una buena manera de acercarse a la celebración: comenzar por lo particular. Preguntar a quién se recuerda, quién preparó la ofrenda y qué decidió incluir. Después, ampliar la mirada hacia la familia, la comunidad y la historia. Un altar de museo puede honrar a una figura pública; una ofrenda doméstica puede reunir varias generaciones. Sus propósitos se relacionan, pero también importan el lugar y los vínculos. "}, "kind": "chapter", "anchor": "in-view", "children": ["names", "hospitality", "calendar", "feelings", "floor-memory"], "group": "memory", "level": 1, "moves": {"up": "welcome", "down": "names", "left": "future", "right": "offering", "forward": null, "backward": null}, "thread": {"en": "No authored temporal connection at this point.", "es": "No hay una conexión temporal escrita para este punto."}}, {"id": "names", "parent": "memory", "photo": "90720204", "sources": ["smithsonian", "facts"], "title": {"en": "What a name makes visible", "es": "Lo que un nombre hace visible"}, "body": {"en": "A name can interrupt the anonymity of a crowd. On an offering, it directs attention toward a person rather than death in the abstract. The surrounding objects can make the identification richer: this person liked this dish; someone kept this photograph; someone remembers a habit worth smiling about.\n\nThese connections are an invitation to ask, not evidence that an outsider can decode everything. A picture may show several people, and an object may have a private meaning. When an account supplies a name or explanation, preserve it accurately. When it does not, let the gap remain visible. Remembering well can include recognizing how much of another person's life you do not know.", "es": "Un nombre puede interrumpir el anonimato de una multitud. En una ofrenda dirige la atención hacia una persona, en lugar de hacia la muerte en abstracto. Los objetos que lo acompañan pueden enriquecer esa presencia: a esta persona le gustaba este platillo; alguien conservó su fotografía; alguien recuerda una costumbre que todavía provoca una sonrisa.\n\nEstas relaciones invitan a preguntar, pero no permiten que una persona ajena lo interprete todo. Una imagen puede mostrar a varias personas y un objeto puede tener un significado íntimo. Cuando un relato proporciona un nombre o una explicación, conviene conservarlos con precisión. Cuando no los proporciona, hay que reconocer ese límite. Recordar con cuidado también puede significar admitir cuánto desconocemos de otra vida."}, "kind": "detail", "anchor": "in-view", "children": [], "group": "memory", "level": 2, "moves": {"up": "memory", "down": "floor-memory", "left": "feelings", "right": "hospitality", "forward": null, "backward": null}, "thread": {"en": "No authored temporal connection at this point.", "es": "No hay una conexión temporal escrita para este punto."}}, {"id": "hospitality", "parent": "memory", "photo": "82250462", "sources": ["unesco", "inpi"], "title": {"en": "An offering as hospitality", "es": "La ofrenda como hospitalidad"}, "body": {"en": "One way to understand an ofrenda is through the work of receiving a guest. Food is prepared, a place is arranged, and light marks a welcome. In many Día de Muertos traditions, this hospitality is directed toward departed loved ones whose return is anticipated within the community's beliefs.\n\nThe comparison helps an unfamiliar visitor see that these objects do something together. A glass, a plate, and a candle form an arrangement of care. Yet hospitality is an interpretive doorway, not a complete translation of every community's spiritual life. Prayers, obligations, agricultural cycles, and local histories may be equally important. The deeper route begins by listening to the people who prepare the offering.", "es": "Una manera de comprender la ofrenda es pensar en el trabajo de recibir a una visita. Se prepara comida, se acomoda un lugar y una luz señala la bienvenida. En muchas tradiciones del Día de Muertos, esta hospitalidad se dirige a los seres queridos fallecidos, cuyo regreso se espera dentro de las creencias de la comunidad.\n\nLa comparación ayuda a reconocer que los objetos actúan juntos. Un vaso, un plato y una vela forman una disposición de cuidado. Sin embargo, la hospitalidad es una puerta de interpretación, no una traducción completa de la vida espiritual de todas las comunidades. Los rezos, las obligaciones, los ciclos agrícolas y las historias locales pueden ser igual de importantes. Para profundizar hay que escuchar a quienes preparan la ofrenda."}, "kind": "detail", "anchor": "in-view", "children": [], "group": "memory", "level": 2, "moves": {"up": "memory", "down": "floor-memory", "left": "names", "right": "calendar", "forward": null, "backward": null}, "thread": {"en": "No authored temporal connection at this point.", "es": "No hay una conexión temporal escrita para este punto."}}, {"id": "calendar", "parent": "memory", "photo": "90653338", "sources": ["calendar", "anthology"], "title": {"en": "More than two squares on a calendar", "es": "Más que dos casillas del calendario"}, "body": {"en": "November 1 and 2 are familiar reference dates, connected with the Catholic observances of All Saints and the Faithful Departed. Preparations and commemorations can extend beyond them. Communities may distinguish the reception of children, adults, or people who died in particular circumstances, using calendars that are not identical everywhere.\n\nThis matters when reading a travel caption or a family account. A date from one locality is not a national timetable. Neither does the calendar reveal all the labor beforehand: shopping, growing flowers, cooking, cleaning, and arranging a space. Follow time backward from the candlelit photograph and the celebration becomes a sequence of preparations. Follow it forward and you reach sharing, clearing away, and the return to daily life.", "es": "El primero y el dos de noviembre son fechas conocidas, relacionadas con las celebraciones católicas de Todos los Santos y de los Fieles Difuntos. Los preparativos y las conmemoraciones pueden extenderse más allá. Algunas comunidades distinguen la recepción de niños, adultos o personas que murieron en determinadas circunstancias, siguiendo calendarios que no son iguales en todas partes.\n\nEsto importa al leer el pie de una fotografía o el relato de una familia. La fecha de una localidad no equivale a un calendario nacional. Tampoco revela todo el trabajo previo: comprar, cultivar flores, cocinar, limpiar y preparar un espacio. Si retrocedes desde la fotografía iluminada por velas, encontrarás una secuencia de preparativos. Si avanzas, llegarás al momento de compartir, recoger y volver a la vida cotidiana."}, "kind": "detail", "anchor": "in-view", "children": [], "group": "memory", "level": 2, "moves": {"up": "memory", "down": "floor-memory", "left": "hospitality", "right": "feelings", "forward": null, "backward": null}, "thread": {"en": "No authored temporal connection at this point.", "es": "No hay una conexión temporal escrita para este punto."}}, {"id": "feelings", "parent": "memory", "photo": "76941731", "sources": ["cisneros", "once"], "title": {"en": "Room for more than one feeling", "es": "Espacio para más de una emoción"}, "body": {"en": "A bright photograph can tempt us to summarize a whole culture's relationship with death as cheerful. That conclusion asks an image to do too much. Celebration, affection, religious devotion, loss, fatigue, and humor can share a setting. Different people may be having very different experiences within the same gathering.\n\nApproach the photograph through what it shows: candlelight, people gathered, flowers arranged. Then separate observation from interpretation. We can recognize work and attention without assigning a feeling to every face. If you bring a memory of your own to this ORB, it need not match an expected mood. You can stay with curiosity, remember someone, or simply learn about the practices of others.", "es": "Una fotografía luminosa puede tentarnos a resumir la relación de toda una cultura con la muerte como alegre. Esa conclusión le exige demasiado a una imagen. La celebración, el cariño, la devoción religiosa, la pérdida, el cansancio y el humor pueden compartir un mismo lugar. Dentro de una reunión, cada persona puede vivir algo distinto.\n\nAcércate a la fotografía por lo que muestra: luz de velas, personas reunidas, flores acomodadas. Después distingue la observación de la interpretación. Podemos reconocer trabajo y atención sin atribuir una emoción a cada rostro. Si traes un recuerdo propio a este ORB, no tiene que ajustarse a un ánimo esperado. Puedes quedarte con la curiosidad, recordar a alguien o simplemente conocer las prácticas de otras personas."}, "kind": "detail", "anchor": "in-view", "children": [], "group": "memory", "level": 2, "moves": {"up": "memory", "down": "floor-memory", "left": "calendar", "right": "names", "forward": null, "backward": null}, "thread": {"en": "No authored temporal connection at this point.", "es": "No hay una conexión temporal escrita para este punto."}}, {"id": "floor-memory", "parent": "memory", "photo": "9457365", "sources": ["anthology", "cisneros"], "title": {"en": "What can a photograph never tell us?", "es": "¿Qué no puede decirnos una fotografía?"}, "body": {"en": "Knowledge floor · A limit of this collection. The photographs establish that particular arrangements and gatherings were documented. They cannot establish the inner experience of the people shown, the complete family history of an offering, or how every participant understands the return of the dead.\n\nThe next inquiry would be specific: how do the makers describe this offering in their own words? A recorded conversation, obtained with consent and preserved with its context, could deepen that account. It would still be one account, rather than a national answer. This ORB has no interviews with the photographed families. Its images invite attention; they do not supply invented testimony.", "es": "Límite del conocimiento · Un límite de esta colección. Las fotografías muestran que se documentaron ciertos arreglos y reuniones. No permiten establecer la experiencia interior de las personas, la historia familiar completa de una ofrenda ni cómo entiende cada participante el regreso de los difuntos.\n\nLa siguiente pregunta sería concreta: ¿cómo describen esta ofrenda sus creadores, con sus propias palabras? Una conversación grabada con consentimiento y conservada en su contexto podría profundizar el relato. Seguiría siendo un testimonio particular, no una respuesta nacional. Este ORB no contiene entrevistas con las familias fotografiadas. Sus imágenes invitan a prestar atención; no ofrecen testimonios inventados."}, "kind": "floor", "anchor": "in-view", "children": [], "group": "memory", "level": 3, "moves": {"up": "memory", "down": null, "left": "floor-future", "right": "floor-symbols", "forward": null, "backward": null}, "thread": {"en": "No authored temporal connection at this point.", "es": "No hay una conexión temporal escrita para este punto."}, "boundary": {"en": "Collection / evidence gap; not a claim that no one knows.", "es": "Límite de esta colección y sus fuentes; no significa que nadie lo sepa."}}, {"id": "offering", "parent": "welcome", "photo": "94845987", "sources": ["inpi", "cdmx"], "title": {"en": "The ofrenda: objects in relationship", "es": "La ofrenda: objetos relacionados"}, "body": {"en": "An ofrenda is easiest to misunderstand when it becomes a checklist. Photographs, candles, flowers, water, food, and other elements often appear together, but there is no single arrangement that describes every household or region. Meanings can overlap, and family choices can be as important as widely shared explanations.\n\nLook at relationships rather than counting items. A path leads toward a table; light draws attention to a portrait; food connects the arrangement to a kitchen and a remembered preference. In this branch, the objects open into those relationships. The source explanations are guides to documented practices. They are not instructions for judging whether someone else's remembrance is correct.", "es": "Es fácil malinterpretar una ofrenda cuando se convierte en una lista de requisitos. Fotografías, velas, flores, agua, comida y otros elementos suelen aparecer juntos, pero ninguna disposición describe todos los hogares o regiones. Los significados pueden coincidir y las decisiones familiares pueden importar tanto como las explicaciones más difundidas.\n\nObserva las relaciones en lugar de contar objetos. Un camino conduce a una mesa; la luz destaca un retrato; la comida vincula el conjunto con una cocina y con un gusto recordado. En esta parte del ORB, los objetos nos llevan hacia esas relaciones. Las fuentes orientan sobre prácticas documentadas. No sirven para juzgar si la manera de recordar de otra persona es correcta."}, "kind": "chapter", "anchor": "in-view", "children": ["flowers", "light", "water", "space", "floor-symbols"], "group": "offering", "level": 1, "moves": {"up": "welcome", "down": "flowers", "left": "memory", "right": "hands", "forward": "sharing", "backward": "hands"}, "thread": {"en": "Temporal thread: earlier / later; sequence does not imply a single cause.", "es": "Hilo temporal: antes / después; la secuencia no implica una causa única."}}, {"id": "flowers", "parent": "offering", "photo": "63761027", "sources": ["inpi", "regions"], "title": {"en": "Cempasúchil: a path of color", "es": "Cempasúchil: un camino de color"}, "body": {"en": "Cempasúchil is one of the most recognizable flowers associated with Día de Muertos. Its orange and yellow presence appears in bunches, arches, arrangements, and paths of petals. In explanations recorded by INPI, flowers and their fragrance are connected with welcoming and guiding the dead.\n\nNotice how differently the same flower can shape a space. A handful of petals can mark a small route; an arch can frame an entrance; a mass of blossoms can transform a public square. The flower is also grown, cut, transported, purchased, and handled. Following it from the offering back toward the field lets spiritual significance and agricultural work remain in the same picture.", "es": "El cempasúchil es una de las flores más reconocibles del Día de Muertos. Su presencia naranja y amarilla aparece en ramos, arcos, arreglos y caminos de pétalos. En las explicaciones recogidas por el INPI, las flores y su aroma se relacionan con la bienvenida y la orientación de los difuntos.\n\nObserva las distintas maneras en que una misma flor organiza el espacio. Un puñado de pétalos puede señalar una pequeña ruta; un arco puede enmarcar una entrada; muchas flores pueden transformar una plaza. La flor también se cultiva, se corta, se transporta, se compra y se acomoda. Seguirla desde la ofrenda hasta el campo permite mantener juntos su significado espiritual y el trabajo agrícola."}, "kind": "detail", "anchor": "in-view", "children": [], "group": "offering", "level": 2, "moves": {"up": "offering", "down": "floor-symbols", "left": "space", "right": "light", "forward": null, "backward": null}, "thread": {"en": "No authored temporal connection at this point.", "es": "No hay una conexión temporal escrita para este punto."}}, {"id": "light", "parent": "offering", "photo": "82440944", "sources": ["inpi", "unesco"], "title": {"en": "What the candle illuminates", "es": "Lo que ilumina la vela"}, "body": {"en": "In documented explanations of the ofrenda, candlelight offers guidance for the returning souls. At the level of the visible scene, a flame also changes what the eye can find: a face in a photograph, the edge of a glass, the texture of a flower. A small light gives an arrangement a center of attention.\n\nThat visual effect should not be mistaken for the whole meaning of the candle. Prayer, dedication, and local practice can determine its role. A photograph taken at night may emphasize flames so strongly that surrounding work or ordinary conversation disappears from view. Look at both nighttime and daytime images when possible. Each reveals a different part of the same place.", "es": "En las explicaciones documentadas de la ofrenda, la luz de las velas orienta a las almas que regresan. En la escena visible, una llama también cambia lo que puede encontrar la mirada: un rostro en una fotografía, el borde de un vaso, la textura de una flor. Una luz pequeña le da al conjunto un centro de atención.\n\nEse efecto visual no debe confundirse con todo el significado de la vela. El rezo, la dedicatoria y la práctica local pueden determinar su función. Una fotografía nocturna puede destacar tanto las llamas que deje fuera el trabajo cercano o las conversaciones cotidianas. Cuando sea posible, observa imágenes del mismo lugar de noche y de día. Cada una revela una parte distinta."}, "kind": "detail", "anchor": "in-view", "children": [], "group": "offering", "level": 2, "moves": {"up": "offering", "down": "floor-symbols", "left": "flowers", "right": "water", "forward": null, "backward": null}, "thread": {"en": "No authored temporal connection at this point.", "es": "No hay una conexión temporal escrita para este punto."}}, {"id": "water", "parent": "offering", "photo": "89770286", "sources": ["agua", "inpi"], "title": {"en": "A glass of water, a gesture of care", "es": "Un vaso de agua, un gesto de cuidado"}, "body": {"en": "Water can be the least spectacular object on a richly decorated table. Its plainness makes it worth a closer look. CONAGUA and INPI explain its presence through quenching the thirst of the souls after their journey. INPI also describes salt in relation to purification. These are accounts of symbolic and religious meaning, not physical claims about an observable visitor.\n\nA simple glass asks us to notice provision rather than ornament. The arrangement remembers needs as well as appearances. This gives a useful contrast of scale: an enormous parade figure draws a crowd, while a glass can direct attention toward intimate care. Both may belong to the season, though they do different work.", "es": "El agua puede ser el objeto menos espectacular de una mesa muy adornada. Su sencillez merece una mirada más atenta. La CONAGUA y el INPI explican su presencia como una forma de aliviar la sed de las almas después del camino. El INPI también relaciona la sal con la purificación. Son explicaciones de significado simbólico y religioso, no afirmaciones físicas sobre una visita observable.\n\nUn vaso sencillo nos invita a notar el acto de ofrecer, además del adorno. La disposición recuerda necesidades y no solo apariencias. Así aparece un contraste de escala: una figura enorme del desfile atrae una multitud, mientras que un vaso puede dirigir la atención hacia un cuidado íntimo. Ambos pueden pertenecer a la temporada, aunque cumplan funciones distintas."}, "kind": "detail", "anchor": "in-view", "children": [], "group": "offering", "level": 2, "moves": {"up": "offering", "down": "floor-symbols", "left": "light", "right": "space", "forward": null, "backward": null}, "thread": {"en": "No authored temporal connection at this point.", "es": "No hay una conexión temporal escrita para este punto."}}, {"id": "space", "parent": "offering", "photo": "36685212", "sources": ["cdmx", "anthology"], "title": {"en": "A table, an arch, a room", "es": "Una mesa, un arco, una habitación"}, "body": {"en": "The shape of an offering changes how you approach it. A table places objects within reach. A tall arrangement draws the eye upward. An arch creates a threshold. Public installations may invite movement around them, while a home setting places remembrance among the furniture and routines of daily life.\n\nIt is tempting to assign the same meaning to every level or direction. The safer and more interesting question is local: what explanation accompanies this arrangement? The photographs of Huaquechula, for example, show striking vertical structures with fabric, religious imagery, flowers, and offerings. Their particular form deserves its own context. Let architecture be a reason to investigate, rather than a shortcut to a universal symbolic code.", "es": "La forma de una ofrenda modifica la manera de acercarse. Una mesa coloca los objetos al alcance. Una estructura alta dirige la mirada hacia arriba. Un arco crea un umbral. Las instalaciones públicas pueden invitar a recorrerlas, mientras que en un hogar el recuerdo convive con los muebles y las rutinas diarias.\n\nResulta tentador atribuir el mismo significado a cada nivel o dirección. Una pregunta más cuidadosa e interesante sería local: ¿qué explicación acompaña este arreglo? Las fotografías de Huaquechula, por ejemplo, muestran estructuras verticales con telas, imágenes religiosas, flores y ofrendas. Su forma particular merece contexto propio. Dejemos que la arquitectura motive la investigación, en vez de usarla como atajo hacia un código simbólico universal."}, "kind": "detail", "anchor": "in-view", "children": [], "group": "offering", "level": 2, "moves": {"up": "offering", "down": "floor-symbols", "left": "water", "right": "flowers", "forward": null, "backward": null}, "thread": {"en": "No authored temporal connection at this point.", "es": "No hay una conexión temporal escrita para este punto."}}, {"id": "floor-symbols", "parent": "offering", "photo": "94342731", "sources": ["inpi", "anthology"], "title": {"en": "Does every symbol have one meaning?", "es": "¿Cada símbolo tiene un solo significado?"}, "body": {"en": "Knowledge floor · A limit of general explanations. Reference lists help identify commonly described elements. They cannot prove that every family uses an object for the same reason, or that a meaning has remained unchanged for centuries. Repetition across websites is not the same as independent historical evidence.\n\nA deeper inquiry would compare accounts from named communities, recorded at different times, and ask who supplied each explanation. Photographs could show changes in arrangement; interviews and documents could explain some of those changes. Here, the specific gap is a comparative history of each symbol. The ORB offers documented starting points and keeps family meanings open to the people who hold them.", "es": "Límite del conocimiento · Un límite de las explicaciones generales. Las listas de referencia ayudan a reconocer elementos frecuentes. No demuestran que todas las familias usen un objeto por la misma razón ni que su significado haya permanecido igual durante siglos. Una explicación repetida en muchas páginas no equivale a evidencia histórica independiente.\n\nPara profundizar habría que comparar relatos de comunidades identificadas, registrados en distintos momentos, y preguntar quién aportó cada explicación. Las fotografías podrían mostrar cambios; las entrevistas y los documentos podrían explicar algunos. Aquí falta una historia comparativa de cada símbolo. El ORB ofrece puntos de partida documentados y deja los significados familiares en manos de quienes los conservan."}, "kind": "floor", "anchor": "in-view", "children": [], "group": "offering", "level": 3, "moves": {"up": "offering", "down": null, "left": "floor-memory", "right": "floor-craft", "forward": null, "backward": null}, "thread": {"en": "No authored temporal connection at this point.", "es": "No hay una conexión temporal escrita para este punto."}, "boundary": {"en": "Collection / evidence gap; not a claim that no one knows.", "es": "Límite de esta colección y sus fuentes; no significa que nadie lo sepa."}}, {"id": "hands", "parent": "welcome", "photo": "94847618", "sources": ["regions", "once"], "title": {"en": "The hands behind the celebration", "es": "Las manos que hacen la celebración"}, "body": {"en": "A finished altar or a moving parade can hide the hours that made it possible. Dough was mixed; paper was cut; flowers were tended; objects were carried, painted, and arranged. Beauty arrives through work. Looking at that work changes the celebration from a collection of images into a network of skills and relationships.\n\nThis branch follows materials: flower, bread, paper, sugar. Each has its own textures and ways of being handled. A film of a maker can show gestures that a still photograph cannot explain. Watch for tools, sequence, and decisions. Who knows when dough is ready? Which parts of the paper must remain connected? What has to happen before the finished object can travel to the offering?", "es": "Un altar terminado o un desfile en movimiento pueden ocultar las horas que los hicieron posibles. Alguien mezcló la masa, recortó el papel, cuidó las flores, cargó objetos, pintó y acomodó. La belleza llega a través del trabajo. Observarlo transforma una colección de imágenes en una red de habilidades y relaciones.\n\nEsta parte sigue los materiales: flor, pan, papel y azúcar. Cada uno tiene texturas y maneras propias de trabajarse. Un video de una persona artesana puede mostrar gestos que una fotografía no explica. Observa las herramientas, la secuencia y las decisiones. ¿Quién sabe cuándo está lista la masa? ¿Qué partes del papel deben permanecer unidas? ¿Qué tiene que ocurrir antes de llevar el objeto terminado a la ofrenda?"}, "kind": "chapter", "anchor": "in-view", "children": ["field", "bread", "paper", "sugar", "floor-craft"], "group": "hands", "level": 1, "moves": {"up": "welcome", "down": "field", "left": "offering", "right": "places", "forward": "offering", "backward": "field"}, "thread": {"en": "Temporal thread: earlier / later; sequence does not imply a single cause.", "es": "Hilo temporal: antes / después; la secuencia no implica una causa única."}}, {"id": "field", "parent": "hands", "photo": "111981010", "sources": ["regions", "unesco"], "title": {"en": "Before the flower reaches the altar", "es": "Antes de que la flor llegue al altar"}, "body": {"en": "The marigold field widens the scene. Before flowers become an arch or a path, they are living plants in a cultivated place. The photograph shows an agricultural landscape rather than a finished ritual arrangement. Connecting those two views helps us notice the growers and the seasonal work behind a familiar symbol.\n\nUNESCO places the Indigenous festivities it describes near the completion of the annual maize cultivation cycle. That relationship does not mean every urban celebration follows the same agricultural schedule. It does suggest a deeper route: trace the actual food and flowers in one locality. Their origins can connect the offering to weather, land, markets, and the people whose labor supplies the gathering.", "es": "El campo de cempasúchil amplía la escena. Antes de formar un arco o un camino, las flores son plantas vivas en un lugar cultivado. La fotografía muestra un paisaje agrícola, todavía sin convertirse en un arreglo ritual. Relacionar esas dos imágenes ayuda a reconocer a quienes cultivan y el trabajo estacional detrás de un símbolo conocido.\n\nLa UNESCO sitúa las fiestas indígenas que describe cerca del cierre del ciclo anual del cultivo del maíz. Esto no significa que toda celebración urbana siga el mismo calendario agrícola. Sí propone una ruta para profundizar: seguir los alimentos y las flores de una localidad concreta. Su procedencia puede vincular la ofrenda con el clima, la tierra, los mercados y el trabajo que sostiene la reunión."}, "kind": "detail", "anchor": "in-view", "children": [], "group": "hands", "level": 2, "moves": {"up": "hands", "down": "floor-craft", "left": "sugar", "right": "bread", "forward": "hands", "backward": null}, "thread": {"en": "Temporal thread: earlier / later; sequence does not imply a single cause.", "es": "Hilo temporal: antes / después; la secuencia no implica una causa única."}}, {"id": "bread", "parent": "hands", "photo": "36716547", "sources": ["regions", "anthology"], "title": {"en": "Bread carries a local signature", "es": "El pan lleva una firma local"}, "body": {"en": "Pan de muerto is a useful name for a family of breads rather than one universal design. The familiar rounded loaf with raised dough decorations is one recognizable form. The gallery also includes a differently shaped bread identified by its photographer with Putla de Guerrero, Oaxaca. A close view makes variety harder to overlook.\n\nTexture matters too: a cut surface reveals crumb, while an overhead view emphasizes decoration. Bread connects remembrance to a skilled sequence of mixing, shaping, proofing, and baking. A recipe video can help you observe one method, but it should retain its maker and place. One recipe is an invitation into a tradition; it does not replace the many recipes that people actually use.", "es": "Pan de muerto es un nombre útil para una familia de panes, no para un único diseño universal. La hogaza redonda con adornos de masa en relieve es una forma reconocible. La galería también incluye un pan de otra forma, identificado por su fotógrafo con Putla de Guerrero, Oaxaca. Una mirada cercana hace más difícil pasar por alto esa variedad.\n\nTambién importa la textura: un corte revela la miga, mientras una toma desde arriba destaca la decoración. El pan conecta el recuerdo con una secuencia de habilidades: mezclar, formar, fermentar y hornear. Un video puede mostrar un método, pero conviene conservar el nombre de quien lo prepara y su contexto. Una receta abre una puerta; no sustituye las muchas recetas que se utilizan."}, "kind": "detail", "anchor": "in-view", "children": [], "group": "hands", "level": 2, "moves": {"up": "hands", "down": "floor-craft", "left": "field", "right": "paper", "forward": null, "backward": null}, "thread": {"en": "No authored temporal connection at this point.", "es": "No hay una conexión temporal escrita para este punto."}}, {"id": "paper", "parent": "hands", "photo": "124997084", "sources": ["regions", "art"], "title": {"en": "Paper that lets the sky through", "es": "Papel que deja pasar el cielo"}, "body": {"en": "Papel picado makes an image partly by removing material. The remaining paper holds figures and patterns together, while the openings let light and background become part of the design. Hanging above a street or an offering, the pieces also reveal air through their movement.\n\nLook closely before reading the motifs as a fixed code. Paper decorations can carry names, local landmarks, skeletons, or other designs chosen for a particular event. A workshop film lets you follow the maker's tools and the structure that keeps a delicate sheet intact. The object is brief and fragile, yet the skill behind it can be taught and practiced repeatedly. That difference between an object's lifespan and a craft's continuity is worth holding onto.", "es": "El papel picado crea una imagen, en parte, al quitar material. Lo que queda sostiene figuras y patrones; las aberturas permiten que la luz y el fondo formen parte del diseño. Cuando las piezas cuelgan sobre una calle o una ofrenda, su movimiento también hace visible el aire.\n\nMira con atención antes de interpretar los motivos como un código fijo. Los adornos pueden incluir nombres, lugares reconocibles, esqueletos u otros diseños elegidos para un evento. Un video de taller permite seguir las herramientas y la estructura que mantiene unida una hoja delicada. El objeto puede ser breve y frágil, mientras que la habilidad para hacerlo se enseña y se practica muchas veces. Vale la pena distinguir la duración del objeto de la continuidad del oficio."}, "kind": "detail", "anchor": "in-view", "children": [], "group": "hands", "level": 2, "moves": {"up": "hands", "down": "floor-craft", "left": "bread", "right": "sugar", "forward": null, "backward": null}, "thread": {"en": "No authored temporal connection at this point.", "es": "No hay una conexión temporal escrita para este punto."}}, {"id": "sugar", "parent": "hands", "photo": "94845993", "sources": ["facts", "inpi"], "title": {"en": "A skull made by a confectioner", "es": "Una calavera hecha por manos dulceras"}, "body": {"en": "A sugar skull joins a recognizable image of mortality to a material associated with sweetness. The examples in the gallery show how much variation exists within that meeting: different colors, sizes, surfaces, and decorations. Some confectionery figures extend beyond a skull into a dressed character.\n\nThe visual combination can feel playful, but a photograph does not tell you whether a particular piece was made for an offering, a market, a display, or a gift. Follow the caption and the maker where possible. There is a useful question beneath the bright icing: what changes when an image can also be handled, offered, purchased, or eaten? Materials shape the ways an image enters everyday life.", "es": "Una calavera de azúcar reúne una imagen reconocible de la mortalidad con un material asociado a lo dulce. Los ejemplos de la galería muestran la variedad de ese encuentro: colores, tamaños, superficies y decoraciones diferentes. Algunas figuras de confitería van más allá del cráneo y se convierten en personajes vestidos.\n\nLa combinación visual puede resultar juguetona, pero una fotografía no indica por sí sola si la pieza se hizo para una ofrenda, un mercado, una exposición o un regalo. Sigue el pie de foto y la información de quien la elaboró cuando sea posible. Bajo el glaseado aparece una pregunta: ¿qué cambia cuando una imagen también puede tocarse, ofrecerse, comprarse o comerse? Los materiales influyen en cómo entra una imagen en la vida cotidiana."}, "kind": "detail", "anchor": "in-view", "children": [], "group": "hands", "level": 2, "moves": {"up": "hands", "down": "floor-craft", "left": "paper", "right": "field", "forward": null, "backward": null}, "thread": {"en": "No authored temporal connection at this point.", "es": "No hay una conexión temporal escrita para este punto."}}, {"id": "floor-craft", "parent": "hands", "photo": "63839452", "sources": ["regions", "anthology"], "title": {"en": "What does a finished object leave out?", "es": "¿Qué deja fuera un objeto terminado?"}, "body": {"en": "Knowledge floor · Missing production histories. The collection shows real objects, but it does not document every maker, workshop, price, supply chain, or method. A beautiful result alone cannot tell us whether the people who made it were paid fairly or whether their skills are being passed on.\n\nTo go deeper, follow one object through a workshop with the maker's consent. Record materials, tools, time, decisions, and the maker's own account of learning. Compare that record with how the object is credited at its destination. This is a proposed inquiry, not a finding about the craftspeople in these images. The present boundary is the information available with the photographs.", "es": "Límite del conocimiento · Faltan historias de producción. La colección muestra objetos reales, pero no documenta a todas las personas que los hicieron, sus talleres, precios, materiales o métodos. Un resultado hermoso no permite saber si el trabajo recibió un pago justo o si los conocimientos se están transmitiendo.\n\nPara profundizar, se podría seguir un objeto en el taller con consentimiento de quien lo elabora. Registrar materiales, herramientas, tiempo, decisiones y su relato de aprendizaje. Después, comparar ese registro con el reconocimiento que recibe el objeto en su destino. Es una propuesta de investigación, no una conclusión sobre las personas de estas imágenes. El límite actual es la información que acompaña las fotografías."}, "kind": "floor", "anchor": "in-view", "children": [], "group": "hands", "level": 3, "moves": {"up": "hands", "down": null, "left": "floor-symbols", "right": "floor-places", "forward": null, "backward": null}, "thread": {"en": "No authored temporal connection at this point.", "es": "No hay una conexión temporal escrita para este punto."}, "boundary": {"en": "Collection / evidence gap; not a claim that no one knows.", "es": "Límite de esta colección y sus fuentes; no significa que nadie lo sepa."}}, {"id": "places", "parent": "welcome", "photo": "90652927", "sources": ["anthology", "regions"], "title": {"en": "Many places, many ways of welcoming", "es": "Muchos lugares, muchas formas de recibir"}, "body": {"en": "The name Día de Muertos can make distinct places seem like versions of a single scene. Regional accounts restore the differences. The lake region of Michoacán, Maya communities in the Yucatán Peninsula, the Huasteca, and Huaquechula in Puebla do not share one interchangeable ritual setting.\n\nThis branch offers four starting points rather than a complete map of Mexico. Move between them slowly. Notice which community and location each source names, which language appears, and whether the photograph records a household observance, a public presentation, or a performance elsewhere. Comparison becomes more interesting when details retain their addresses. Shared flowers or dates can connect the scenes without erasing the people and histories that distinguish them.", "es": "El nombre Día de Muertos puede hacer que lugares distintos parezcan versiones de una sola escena. Los relatos regionales recuperan las diferencias. La región lacustre de Michoacán, las comunidades mayas de la península de Yucatán, la Huasteca y Huaquechula, en Puebla, no comparten un contexto ritual intercambiable.\n\nEsta parte ofrece cuatro puntos de partida, no un mapa completo de México. Recorre los lugares con calma. Observa qué comunidad y localidad nombra cada fuente, qué lengua aparece y si la fotografía registra una práctica doméstica, una presentación pública o un espectáculo realizado en otro lugar. La comparación se vuelve más interesante cuando los detalles conservan su procedencia. Compartir flores o fechas permite relacionar las escenas sin borrar sus diferencias."}, "kind": "chapter", "anchor": "in-view", "children": ["michoacan", "yucatan", "huasteca", "huaquechula", "floor-places"], "group": "places", "level": 1, "moves": {"up": "welcome", "down": "michoacan", "left": "hands", "right": "histories", "forward": null, "backward": null}, "thread": {"en": "No authored temporal connection at this point.", "es": "No hay una conexión temporal escrita para este punto."}}, {"id": "michoacan", "parent": "places", "photo": "76651907", "sources": ["regions", "anthology"], "title": {"en": "Michoacán: the lake and the vigil", "es": "Michoacán: el lago y la vigilia"}, "body": {"en": "Janitzio and other communities around Lake Pátzcuaro are associated with Noche de Muertos and Purépecha traditions of honoring the departed. The cemetery photographs offer striking differences of light and viewpoint: paths, flowers, arrangements, visitors, and candles all share the frame. They are records of particular moments rather than timeless portraits of a whole people.\n\nThe deeper question is how remembrance is sustained before and after the famous night. INAH's regional account emphasizes communal preparation and the sharing of food. A photograph of a vigil is therefore an opening into ongoing relationships. Keep the named locality in view, and let community accounts guide the interpretation of what the image alone cannot explain.", "es": "Janitzio y otras comunidades alrededor del lago de Pátzcuaro se relacionan con la Noche de Muertos y con tradiciones purépechas de honra a los difuntos. Las fotografías del panteón ofrecen diferencias notables de luz y perspectiva: caminos, flores, arreglos, visitantes y velas comparten el encuadre. Registran momentos particulares, no retratos eternos de todo un pueblo.\n\nLa pregunta más profunda es cómo se sostiene el recuerdo antes y después de esa noche conocida. El relato regional del INAH destaca los preparativos comunitarios y el acto de compartir alimentos. Una fotografía de la vigilia abre así una puerta hacia relaciones continuas. Conserva a la vista la localidad nombrada y permite que los relatos de la comunidad orienten lo que la imagen por sí sola no explica."}, "kind": "detail", "anchor": "in-view", "children": [], "group": "places", "level": 2, "moves": {"up": "places", "down": "floor-places", "left": "huaquechula", "right": "yucatan", "forward": null, "backward": null}, "thread": {"en": "No authored temporal connection at this point.", "es": "No hay una conexión temporal escrita para este punto."}}, {"id": "yucatan", "parent": "places", "photo": "82250466", "sources": ["regions", "pomuch"], "title": {"en": "Hanal Pixán: food for the souls", "es": "Hanal Pixán: comida para las almas"}, "body": {"en": "Hanal Pixán, also written Janal Pixan, names a Maya tradition in the Yucatán Peninsula commonly translated as food for the souls. The words themselves shift the emphasis toward offering nourishment. The photographs show food, tables, cloth, religious images, and people participating in a particular documented setting.\n\nThe peninsula also contains significant local differences. INAH documents the care and cleaning of ancestral bones in Pomuch, Campeche; that practice should not be assigned to every Maya community. This ORB keeps that topic in a source link rather than using images of human remains for atmosphere. Follow the community name as carefully as the shared tradition name. A regional label begins an inquiry; a local account makes it more precise.", "es": "Hanal Pixán, también escrito Janal Pixan, nombra una tradición maya de la península de Yucatán que suele traducirse como comida para las almas. Las propias palabras llevan la atención hacia el alimento ofrecido. Las fotografías muestran comida, mesas, manteles, imágenes religiosas y personas que participan en un contexto documentado.\n\nDentro de la península existen diferencias locales importantes. El INAH documenta el cuidado y la limpieza de los huesos de los antepasados en Pomuch, Campeche; esta práctica no debe atribuirse a todas las comunidades mayas. El ORB conserva ese tema en un enlace de consulta. Sigue el nombre de la comunidad con el mismo cuidado que el de la tradición compartida. Una etiqueta regional inicia la investigación; un relato local la vuelve más precisa."}, "kind": "detail", "anchor": "in-view", "children": [], "group": "places", "level": 2, "moves": {"up": "places", "down": "floor-places", "left": "michoacan", "right": "huasteca", "forward": null, "backward": null}, "thread": {"en": "No authored temporal connection at this point.", "es": "No hay una conexión temporal escrita para este punto."}}, {"id": "huasteca", "parent": "places", "photo": "139963032", "sources": ["xantolo", "huehues"], "title": {"en": "Xantolo: the gathering extends outward", "es": "Xantolo: la reunión se extiende"}, "body": {"en": "Xantolo is associated with the Huasteca, a region with several Indigenous peoples and local traditions. UNESCO's account from the Huasteca Potosina describes offerings, community hospitality, food, and masked dancers. In that account, remembrance reaches beyond a household into shared responsibilities and encounters.\n\nThe photographs here need careful reading. Musicians photographed in Huejutla, a Huasteca community festival in Xalapa, and a university dance company performing Xantolo are different kinds of evidence. A stage performance can introduce movement and costume, but it is not a recording of a household ritual. Keeping these distinctions visible helps us appreciate both cultural practice and the work of presenting it to new audiences.", "es": "El Xantolo se asocia con la Huasteca, una región donde conviven varios pueblos indígenas y tradiciones locales. El relato de la UNESCO sobre la Huasteca Potosina describe ofrendas, hospitalidad comunitaria, alimentos y danzantes enmascarados. En ese relato, el recuerdo se extiende más allá del hogar hacia responsabilidades y encuentros compartidos.\n\nLas fotografías requieren una lectura atenta. Unos músicos en Huejutla, un festival de la comunidad huasteca en Xalapa y una compañía universitaria que interpreta una danza de Xantolo son evidencias distintas. Una presentación escénica puede mostrar movimiento y vestuario, pero no registra un ritual doméstico. Conservar estas diferencias permite apreciar tanto las prácticas culturales como el trabajo de presentarlas a otros públicos."}, "kind": "detail", "anchor": "in-view", "children": [], "group": "places", "level": 2, "moves": {"up": "places", "down": "floor-places", "left": "yucatan", "right": "huaquechula", "forward": null, "backward": null}, "thread": {"en": "No authored temporal connection at this point.", "es": "No hay una conexión temporal escrita para este punto."}}, {"id": "huaquechula", "parent": "places", "photo": "90469908", "sources": ["anthology"], "title": {"en": "Huaquechula: remembrance rises through a room", "es": "Huaquechula: el recuerdo ocupa la habitación"}, "body": {"en": "The photographs from Huaquechula, Puebla, show tall offerings whose fabric, flowers, religious imagery, and carefully arranged objects transform an interior. Their vertical scale changes the relationship between a visitor and the room. One must look upward as well as toward the offerings close to the floor.\n\nUse these photographs to compare arrangements rather than to invent a rule for every level. The documentary captions identify specific places and, in one case in the gallery, the person honored. That specificity matters. Two images with similar white fabric may still record different dedications and family circumstances. A detailed understanding would come from local makers explaining the construction and meaning of their own altar.", "es": "Las fotografías de Huaquechula, Puebla, muestran ofrendas altas cuyas telas, flores, imágenes religiosas y objetos cuidadosamente acomodados transforman un interior. Su escala vertical cambia la relación entre quien visita y la habitación. Hay que mirar hacia arriba, además de observar lo que se encuentra cerca del suelo.\n\nUtiliza estas fotografías para comparar arreglos, sin inventar una regla para cada nivel. Los pies documentales identifican lugares concretos y, en un caso de la galería, a la persona homenajeada. Esa precisión importa. Dos imágenes con telas blancas parecidas pueden registrar dedicatorias y circunstancias familiares distintas. Para comprenderlas con detalle habría que escuchar a quienes construyeron cada altar explicar su forma y significado."}, "kind": "detail", "anchor": "in-view", "children": [], "group": "places", "level": 2, "moves": {"up": "places", "down": "floor-places", "left": "huasteca", "right": "michoacan", "forward": null, "backward": null}, "thread": {"en": "No authored temporal connection at this point.", "es": "No hay una conexión temporal escrita para este punto."}}, {"id": "floor-places", "parent": "places", "photo": "75281433", "sources": ["anthology", "xantolo"], "title": {"en": "Who is missing from this map?", "es": "¿Quién falta en este mapa?"}, "body": {"en": "Knowledge floor · Coverage gap. Four regional doorways cannot represent all of Mexico, and English and Spanish do not include all the languages in which these traditions are lived. The present collection also favors places that photographers and cultural institutions have made visible online.\n\nThe next step would be to add community-authored accounts from places currently absent, retaining their language and the authors' chosen terms. A useful comparison would ask what changes when an account is made for neighbors, schoolchildren, tourists, or a national institution. This is a question about representation in this ORB. It is not a claim that the missing communities lack knowledge, documentation, or their own ways of telling their histories.", "es": "Límite del conocimiento · Falta de cobertura. Cuatro puertas regionales no pueden representar todo México, y el inglés y el español no incluyen todas las lenguas en que se viven estas tradiciones. La colección también favorece lugares que fotógrafos e instituciones culturales han hecho visibles en internet.\n\nEl siguiente paso sería incorporar relatos escritos por comunidades ausentes, conservando su lengua y los términos que sus autores elijan. Una comparación útil preguntaría qué cambia cuando un relato se dirige a vecinos, escolares, turistas o una institución nacional. Es una pregunta sobre la representación dentro de este ORB. No significa que las comunidades ausentes carezcan de conocimientos, documentación o maneras propias de narrar su historia."}, "kind": "floor", "anchor": "in-view", "children": [], "group": "places", "level": 3, "moves": {"up": "places", "down": null, "left": "floor-craft", "right": "floor-history", "forward": null, "backward": null}, "thread": {"en": "No authored temporal connection at this point.", "es": "No hay una conexión temporal escrita para este punto."}, "boundary": {"en": "Collection / evidence gap; not a claim that no one knows.", "es": "Límite de esta colección y sus fuentes; no significa que nadie lo sepa."}}, {"id": "histories", "parent": "welcome", "photo": "90854213", "sources": ["history", "art", "change"], "title": {"en": "How the celebration acquired its layers", "es": "Cómo se formaron las capas de la celebración"}, "body": {"en": "The present celebration contains histories that do not all begin at the same moment. Indigenous practices of honoring the dead, Catholic commemorations, family traditions, printed satire, public art, and modern urban events belong to the inquiry. A single origin story is too small to hold those relationships.\n\nThis branch separates layers so that they can be connected more carefully. A skeleton in a print, a home offering, and a parade figure may share imagery without having the same purpose or history. Ask what the evidence documents, when it was produced, and who interpreted it. The more beautiful the present scene becomes, the more worthwhile it is to understand how people made and remade it.", "es": "La celebración actual reúne historias que no comienzan en el mismo momento. Las prácticas indígenas de honra a los difuntos, las conmemoraciones católicas, las tradiciones familiares, la sátira impresa, el arte público y los eventos urbanos modernos forman parte de la investigación. Un solo relato de origen resulta insuficiente.\n\nEsta parte distingue las capas para relacionarlas con cuidado. Un esqueleto en una estampa, una ofrenda doméstica y una figura de desfile pueden compartir imágenes sin tener el mismo propósito ni la misma historia. Pregunta qué documenta la evidencia, cuándo se produjo y quién la interpretó. Cuanto más hermosa resulta la escena presente, más vale la pena comprender cómo las personas la hicieron y la transformaron."}, "kind": "chapter", "anchor": "in-view", "children": ["history-roots", "history-colonial", "history-public", "parade-art", "floor-history"], "group": "histories", "level": 1, "moves": {"up": "welcome", "down": "history-roots", "left": "places", "right": "future", "forward": null, "backward": null}, "thread": {"en": "No authored temporal connection at this point.", "es": "No hay una conexión temporal escrita para este punto."}}, {"id": "history-roots", "parent": "histories", "photo": "29732925", "sources": ["history", "anthology"], "title": {"en": "Indigenous histories, in the plural", "es": "Historias indígenas, en plural"}, "body": {"en": "Indigenous peoples in Mexico have distinct languages, histories, and traditions concerning ancestors and the dead. Naming those differences is more accurate than treating a generic pre-Hispanic past as a complete explanation of a present-day offering. A Maya practice and a Purépecha practice deserve their own sources and terms.\n\nHistorical continuity is a question to investigate through particular evidence. An older description can document a practice in its own setting; it does not automatically establish an uninterrupted line to every modern object. INAH's historical discussion examines differing interpretations of the celebration's origins. Read those interpretations as arguments built from sources. Respect for long histories grows stronger when we resist making them simpler than the evidence allows.", "es": "Los pueblos indígenas de México tienen lenguas, historias y tradiciones distintas en torno a los antepasados y los difuntos. Nombrar esas diferencias es más preciso que usar un pasado prehispánico genérico como explicación completa de una ofrenda actual. Una práctica maya y una purépecha merecen fuentes y términos propios.\n\nLa continuidad histórica debe investigarse mediante evidencias concretas. Una descripción antigua puede documentar una práctica en su contexto; no demuestra automáticamente una línea ininterrumpida hasta cada objeto moderno. El estudio histórico del INAH examina distintas interpretaciones del origen de la celebración. Conviene leerlas como argumentos construidos con fuentes. El respeto por historias largas se fortalece cuando evitamos simplificarlas más de lo que permite la evidencia."}, "kind": "detail", "anchor": "in-view", "children": [], "group": "histories", "level": 2, "moves": {"up": "histories", "down": "floor-history", "left": "parade-art", "right": "history-colonial", "forward": "history-colonial", "backward": null}, "thread": {"en": "Temporal thread: earlier / later; sequence does not imply a single cause.", "es": "Hilo temporal: antes / después; la secuencia no implica una causa única."}}, {"id": "history-colonial", "parent": "histories", "photo": "36685209", "sources": ["calendar", "history"], "title": {"en": "The calendar and the colonial encounter", "es": "El calendario y el encuentro colonial"}, "body": {"en": "The Catholic observances of All Saints and the Faithful Departed are part of the history of the November commemorations. Indigenous practices and Christian forms developed relationships under colonial conditions, including religious pressure and unequal power. The useful word syncretism describes the joining and transformation of religious elements; it should not make the process sound automatic or uniform.\n\nA cross, a prayer, and an offering of food can coexist in a contemporary setting. To explain that setting historically, however, we need more than the present arrangement. Documents, local accounts, and careful comparison help distinguish what can be traced from what is inferred. Cultural change can include adaptation, conflict, and creative continuity at the same time.", "es": "Las celebraciones católicas de Todos los Santos y de los Fieles Difuntos forman parte de la historia de las conmemoraciones de noviembre. Las prácticas indígenas y las formas cristianas se relacionaron en condiciones coloniales, con presión religiosa y desigualdad de poder. La palabra sincretismo describe la unión y transformación de elementos religiosos; no debe hacer que el proceso parezca automático o uniforme.\n\nUna cruz, un rezo y una ofrenda de comida pueden convivir en un contexto actual. Sin embargo, para explicarlo históricamente necesitamos más que observar el arreglo presente. Los documentos, los relatos locales y la comparación cuidadosa distinguen lo que puede rastrearse de lo que se infiere. El cambio cultural puede reunir adaptación, conflicto y continuidad creativa."}, "kind": "detail", "anchor": "in-view", "children": [], "group": "histories", "level": 2, "moves": {"up": "histories", "down": "floor-history", "left": "history-roots", "right": "history-public", "forward": "history-public", "backward": "history-roots"}, "thread": {"en": "Temporal thread: earlier / later; sequence does not imply a single cause.", "es": "Hilo temporal: antes / después; la secuencia no implica una causa única."}}, {"id": "history-public", "parent": "histories", "photo": "17081090", "sources": ["art", "chicano", "change"], "title": {"en": "La Catrina: an image with a sharp edge", "es": "La Catrina: una imagen con filo"}, "body": {"en": "La Catrina belongs to the story of Mexican graphic art and satire. José Guadalupe Posada's calavera imagery used skeletons to comment on the living, including social pretension and elites. Following that history changes how we see an elegant skeletal figure: decoration can carry criticism as well as beauty.\n\nImages travel between media. A printed figure can be reinterpreted as sculpture, costume, face painting, or a monumental parade presence. The gallery shows several such forms, with their own makers and contexts. They should not all be attributed to Posada as individual works. The connection is an evolving visual tradition. Ask what a new medium enlarges, softens, or leaves behind when it carries the image forward.", "es": "La Catrina pertenece a la historia de la gráfica y la sátira mexicanas. Las calaveras de José Guadalupe Posada utilizaban esqueletos para comentar la vida social, incluidas las élites y las pretensiones de estatus. Conocer esa historia cambia nuestra manera de ver una figura esquelética elegante: el adorno puede llevar crítica, además de belleza.\n\nLas imágenes viajan entre medios. Una figura impresa puede reinterpretarse como escultura, vestuario, maquillaje o presencia monumental en un desfile. La galería muestra varias formas, con creadores y contextos propios. No deben atribuirse todas a Posada como obras individuales. Las relaciona una tradición visual en transformación. Pregunta qué amplía, suaviza o deja atrás cada nuevo medio al continuar la imagen."}, "kind": "detail", "anchor": "in-view", "children": [], "group": "histories", "level": 2, "moves": {"up": "histories", "down": "floor-history", "left": "history-colonial", "right": "parade-art", "forward": "parade-art", "backward": "history-colonial"}, "thread": {"en": "Temporal thread: earlier / later; sequence does not imply a single cause.", "es": "Hilo temporal: antes / después; la secuencia no implica una causa única."}}, {"id": "parade-art", "parent": "histories", "photo": "140189125", "sources": ["parade", "change"], "title": {"en": "The parade: many hands, one moving image", "es": "El desfile: muchas manos, una imagen en movimiento"}, "body": {"en": "A parade assembles bodies, costumes, music, structures, and a route through public space. Its beauty depends on coordination: people move together, large forms remain legible at a distance, and successive groups change the rhythm. Watch the official Mexico City footage for those relationships as well as the spectacular figures.\n\nThe film labeled Gran Desfile de Día de Muertos 2024 documents that event even though the cultural authority uploaded it in 2025. An upload date and an event date are different facts. Modern public parades are one layer of the celebration; their visibility should not set the scale for judging family or community observances. A quiet offering and a vast moving procession can both reward close attention.", "es": "Un desfile reúne cuerpos, vestuarios, música, estructuras y una ruta por el espacio público. Su belleza depende de la coordinación: las personas avanzan juntas, las figuras grandes se reconocen a distancia y los grupos sucesivos cambian el ritmo. Observa esas relaciones en el video oficial de la Ciudad de México, además de las figuras espectaculares.\n\nEl video titulado Gran Desfile de Día de Muertos 2024 documenta ese evento, aunque la autoridad cultural lo publicó en 2025. La fecha del evento y la fecha de publicación son datos distintos. Los desfiles públicos modernos forman una capa de la celebración; su visibilidad no debe convertirse en medida para juzgar las prácticas familiares o comunitarias. Una ofrenda tranquila y una gran procesión merecen atención propia."}, "kind": "detail", "anchor": "in-view", "children": [], "group": "histories", "level": 2, "moves": {"up": "histories", "down": "floor-history", "left": "history-public", "right": "history-roots", "forward": "future", "backward": "history-public"}, "thread": {"en": "Temporal thread: earlier / later; sequence does not imply a single cause.", "es": "Hilo temporal: antes / después; la secuencia no implica una causa única."}}, {"id": "floor-history", "parent": "histories", "photo": "63801891", "sources": ["history", "change"], "title": {"en": "How old is this particular practice?", "es": "¿Qué antigüedad tiene esta práctica concreta?"}, "body": {"en": "Knowledge floor · Historical interpretation. The question becomes answerable only after we specify the practice, the place, and the evidence. Asking how old Día de Muertos is can combine different histories into one misleading number. Asking when a certain object, date, procession, or explanation appears in a named locality is more precise.\n\nINAH's historical discussion presents debate around origins and later reinterpretation. To continue, compare primary descriptions and images from different periods, noting who created them and why. A gap in surviving records does not prove a practice did not exist. Nor does a resemblance prove direct descent. This ORB preserves the distinction between documented evidence, interpretation, and a continuity still needing investigation.", "es": "Límite del conocimiento · Interpretación histórica. La pregunta solo puede responderse después de precisar la práctica, el lugar y la evidencia. Preguntar cuántos años tiene el Día de Muertos puede reunir historias distintas en una cifra engañosa. Preguntar cuándo aparece un objeto, una fecha, una procesión o una explicación en una localidad es más preciso.\n\nEl estudio histórico del INAH presenta debates sobre los orígenes y las reinterpretaciones posteriores. Para continuar, conviene comparar descripciones e imágenes de distintas épocas, atendiendo a quién las produjo y para qué. Una ausencia documental no demuestra que una práctica no existiera. Tampoco una semejanza demuestra descendencia directa. El ORB distingue evidencia, interpretación y continuidades que todavía requieren investigación."}, "kind": "floor", "anchor": "in-view", "children": [], "group": "histories", "level": 3, "moves": {"up": "histories", "down": null, "left": "floor-places", "right": "floor-future", "forward": null, "backward": null}, "thread": {"en": "No authored temporal connection at this point.", "es": "No hay una conexión temporal escrita para este punto."}, "boundary": {"en": "Collection / evidence gap; not a claim that no one knows.", "es": "Límite de esta colección y sus fuentes; no significa que nadie lo sepa."}}, {"id": "future", "parent": "welcome", "photo": "76976678", "sources": ["change", "chicano", "publicaltar"], "title": {"en": "A living tradition keeps moving", "es": "Una tradición viva sigue en movimiento"}, "body": {"en": "A tradition continues through people doing things: arranging, explaining, teaching, adapting, disagreeing, and remembering. New settings can change what becomes visible. A family offering, a school project, a museum installation, and a public parade bring different audiences and responsibilities into the picture.\n\nThis final branch follows the celebration beyond a single night. It considers sharing, migration, public remembrance, and the choices we make as viewers. The aim is to leave with a richer way of looking. Beauty can open the door; names, places, work, and evidence help us stay long enough to understand more. Return to the first photograph after this branch and see which details now ask different questions.", "es": "Una tradición continúa cuando las personas hacen cosas: acomodan, explican, enseñan, adaptan, discrepan y recuerdan. Los contextos nuevos pueden cambiar lo que se vuelve visible. Una ofrenda familiar, un proyecto escolar, una instalación de museo y un desfile público reúnen públicos y responsabilidades diferentes.\n\nEsta última parte sigue la celebración más allá de una sola noche. Considera el acto de compartir, la migración, el recuerdo público y nuestras decisiones como espectadores. La intención es salir con una mirada más rica. La belleza abre la puerta; los nombres, los lugares, el trabajo y las fuentes permiten quedarse y comprender más. Vuelve después a la primera fotografía y observa qué detalles despiertan ahora otras preguntas."}, "kind": "chapter", "anchor": "in-view", "children": ["sharing", "migration", "public-memory", "looking", "floor-future"], "group": "future", "level": 1, "moves": {"up": "welcome", "down": "sharing", "left": "histories", "right": "memory", "forward": null, "backward": "parade-art"}, "thread": {"en": "Temporal thread: earlier / later; sequence does not imply a single cause.", "es": "Hilo temporal: antes / después; la secuencia no implica una causa única."}}, {"id": "sharing", "parent": "future", "photo": "75039066", "sources": ["xantolo", "regions"], "title": {"en": "What happens after the offering?", "es": "¿Qué sucede después de la ofrenda?"}, "body": {"en": "A photograph often fixes the moment when everything looks complete. The life of an offering continues beyond that moment. Regional accounts describe food being shared and people gathering around preparation and remembrance. Specific customs about timing and distribution should be learned from the place concerned.\n\nFollowing the sequence afterward changes what counts as part of the celebration. Dishes must be handled, materials cleared, and ordinary spaces used again. Those acts are less likely to become the most famous photograph, yet they belong to the work that makes an annual observance possible. A useful question is what remains when the arrangement is gone: a conversation, a recipe, a responsibility, or a relationship renewed.", "es": "Una fotografía suele fijar el momento en que todo parece completo. La vida de una ofrenda continúa después. Los relatos regionales describen alimentos compartidos y personas reunidas alrededor de los preparativos y del recuerdo. Las costumbres sobre horarios y distribución deben conocerse en el lugar correspondiente.\n\nSeguir la secuencia posterior cambia lo que consideramos parte de la celebración. Hay que recoger platos y materiales, y volver a usar los espacios cotidianos. Esos actos rara vez producen la fotografía más famosa, pero pertenecen al trabajo que hace posible una conmemoración anual. Una pregunta útil es qué permanece cuando desaparece el arreglo: una conversación, una receta, una responsabilidad o una relación renovada."}, "kind": "detail", "anchor": "in-view", "children": [], "group": "future", "level": 2, "moves": {"up": "future", "down": "floor-future", "left": "looking", "right": "migration", "forward": null, "backward": "offering"}, "thread": {"en": "Temporal thread: earlier / later; sequence does not imply a single cause.", "es": "Hilo temporal: antes / después; la secuencia no implica una causa única."}}, {"id": "migration", "parent": "future", "photo": "124997069", "sources": ["chicano", "change"], "title": {"en": "Remembrance crosses a border", "es": "El recuerdo cruza una frontera"}, "body": {"en": "Mexican American communities have their own histories of Día de Muertos. Smithsonian accounts describe the importance of Chicano artists and activists in developing public celebrations in the United States, including work associated with Self Help Graphics in East Los Angeles. Public art could connect remembrance with identity and contemporary community concerns.\n\nThis history complicates the idea that a tradition outside Mexico is merely a copy. People carry practices into new circumstances and give them new forms. At the same time, an image found anywhere in the world should not lose its actual location. The photograph accompanying this reading is a comparison image of public decoration in Mexico; the linked sources provide the specific United States history.", "es": "Las comunidades mexicoamericanas tienen historias propias del Día de Muertos. Los relatos del Smithsonian describen la importancia de artistas y activistas chicanos en el desarrollo de celebraciones públicas en Estados Unidos, incluido el trabajo asociado con Self Help Graphics en el este de Los Ángeles. El arte público podía relacionar el recuerdo con la identidad y las preocupaciones comunitarias del presente.\n\nEsta historia cuestiona la idea de que una tradición fuera de México sea solo una copia. Las personas llevan prácticas a circunstancias nuevas y les dan otras formas. A la vez, una imagen debe conservar su ubicación real. La fotografía de esta lectura muestra decoración pública en México como comparación; las fuentes enlazadas documentan la historia específica de Estados Unidos."}, "kind": "detail", "anchor": "in-view", "children": [], "group": "future", "level": 2, "moves": {"up": "future", "down": "floor-future", "left": "sharing", "right": "public-memory", "forward": null, "backward": null}, "thread": {"en": "No authored temporal connection at this point.", "es": "No hay una conexión temporal escrita para este punto."}}, {"id": "public-memory", "parent": "future", "photo": "140188696", "sources": ["publicaltar", "unam"], "title": {"en": "Who can a public ofrenda remember?", "es": "¿A quién puede recordar una ofrenda pública?"}, "body": {"en": "Public offerings can connect remembrance with concerns shared beyond one family. The United Nations in Mexico has documented offerings connected with peace, while UNAM's 2025 Megaofrenda program addressed migration, exile, and displacement. These named examples show how the form can create a space for public reflection.\n\nAn institution's offering also involves choices: who is named, what is explained, and whose work is acknowledged. A viewer can ask those questions while appreciating the art. The photograph here records a monumental Mexico City installation, not either of the specific institutional examples discussed. Keeping the image caption distinct from the reading's evidence lets the visual comparison enrich the subject without becoming a false identification.", "es": "Las ofrendas públicas pueden relacionar el recuerdo con preocupaciones que van más allá de una familia. Naciones Unidas en México ha documentado ofrendas vinculadas con la paz, mientras que la Megaofrenda de la UNAM de 2025 abordó migraciones, exilios y desplazamientos. Estos ejemplos concretos muestran cómo la forma puede abrir un espacio de reflexión pública.\n\nUna ofrenda institucional también implica decisiones: a quién se nombra, qué se explica y qué trabajo se reconoce. Es posible hacer esas preguntas y apreciar el arte al mismo tiempo. La fotografía muestra una instalación monumental de la Ciudad de México, no los ejemplos institucionales mencionados. Distinguir el pie de foto de las fuentes de la lectura permite comparar sin crear una identificación falsa."}, "kind": "detail", "anchor": "in-view", "children": [], "group": "future", "level": 2, "moves": {"up": "future", "down": "floor-future", "left": "migration", "right": "looking", "forward": null, "backward": null}, "thread": {"en": "No authored temporal connection at this point.", "es": "No hay una conexión temporal escrita para este punto."}}, {"id": "looking", "parent": "future", "photo": "145070295", "sources": ["change", "anthology"], "title": {"en": "How to look with attention", "es": "Cómo mirar con atención"}, "body": {"en": "Begin with the caption: place, maker, date, and setting. A costume photograph may show a public event where posing is part of the encounter. A cemetery photograph may record a much more personal moment. The fact that both images are colorful does not make their circumstances equivalent.\n\nFor this collection, photographs retain their source and license, and videos remain attached to their original publishers. When you explore beyond the ORB, keep asking who made an image and what context has traveled with it. If you attend a celebration, follow the hosts' guidance and ask before photographing people in intimate settings. The most rewarding attention allows someone else's practice to have meaning beyond your experience of seeing it.", "es": "Comienza por el pie de foto: lugar, autoría, fecha y contexto. Un retrato con vestuario puede mostrar un evento público donde posar forma parte del encuentro. Una fotografía de panteón puede registrar un momento mucho más íntimo. Que ambas imágenes sean coloridas no vuelve equivalentes sus circunstancias.\n\nEn esta colección, las fotografías conservan su fuente y licencia, y los videos permanecen vinculados a quienes los publicaron. Cuando explores fuera del ORB, sigue preguntando quién hizo una imagen y qué contexto la acompaña. Si asistes a una celebración, sigue las indicaciones de quienes reciben y pide permiso antes de fotografiar a personas en momentos íntimos. Mirar con atención permite que una práctica tenga significado más allá de nuestra experiencia como espectadores."}, "kind": "detail", "anchor": "in-view", "children": [], "group": "future", "level": 2, "moves": {"up": "future", "down": "floor-future", "left": "public-memory", "right": "sharing", "forward": null, "backward": null}, "thread": {"en": "No authored temporal connection at this point.", "es": "No hay una conexión temporal escrita para este punto."}}, {"id": "floor-future", "parent": "future", "photo": "178035302", "sources": ["anthology", "change"], "title": {"en": "What would it mean to carry this forward?", "es": "¿Qué significaría continuar este recuerdo?"}, "body": {"en": "Knowledge floor · An open personal and curatorial question. This ORB cannot decide how a community should preserve or change its traditions. It can show documented examples, name the limits of its collection, and make room for more accounts. Future additions should be guided by evidence and by the people whose practices are represented.\n\nFor your own reflection, consider one modest question: is there a name, a recipe, or a kindness you would like to carry forward? This is an optional invitation from the ORB, not a claim to prescribe a Mexican ritual. You can also leave with another question to research. Return to the photograph, the flowers, and the favorite dish. Their beauty now has more relationships around it.", "es": "Límite del conocimiento · Una pregunta personal y curatorial abierta. Este ORB no puede decidir cómo debe una comunidad conservar o transformar sus tradiciones. Puede mostrar ejemplos documentados, nombrar los límites de su colección y abrir espacio a otros relatos. Las futuras incorporaciones deben orientarse por las fuentes y por las personas cuyas prácticas se representan.\n\nPara una reflexión propia, considera una pregunta sencilla: ¿hay un nombre, una receta o un gesto de bondad que quisieras conservar? Es una invitación opcional del ORB, no una prescripción de un ritual mexicano. También puedes llevarte otra pregunta para investigar. Vuelve a la fotografía, las flores y el platillo favorito. Su belleza tiene ahora más relaciones a su alrededor."}, "kind": "floor", "anchor": "in-view", "children": [], "group": "future", "level": 3, "moves": {"up": "future", "down": null, "left": "floor-history", "right": "floor-memory", "forward": null, "backward": null}, "thread": {"en": "No authored temporal connection at this point.", "es": "No hay una conexión temporal escrita para este punto."}, "boundary": {"en": "Collection / evidence gap; not a claim that no one knows.", "es": "Límite de esta colección y sus fuentes; no significa que nadie lo sepa."}}], "chapters": ["memory", "offering", "hands", "places", "histories", "future"], "route": ["welcome", "memory", "names", "hospitality", "calendar", "feelings", "floor-memory", "offering", "flowers", "light", "water", "space", "floor-symbols", "hands", "field", "bread", "paper", "sugar", "floor-craft", "places", "michoacan", "yucatan", "huasteca", "huaquechula", "floor-places", "histories", "history-roots", "history-colonial", "history-public", "parade-art", "floor-history", "future", "sharing", "migration", "public-memory", "looking", "floor-future"], "authorship": "Primary assistant authored English prose and Spanish adaptations; Kokoro generated speech only."};